using BC.FixedAsset.Services;using System;using System.Web.UI.WebControls;
namespace BC.FixedAsset.Web.FixedAsset{public partial class AssetTag:SecurePage{protected Literal litNo,litName,litLocation,litCustodian;protected HiddenField hidQr;protected void Page_Load(object s,EventArgs e){if(IsPostBack)return;long id;if(!long.TryParse(Request.QueryString["id"],out id))throw new InvalidOperationException("Invalid survey.");var t=new AssetSurveyService().Detail(id,AssetAccess);if(t.Rows.Count==0)throw new InvalidOperationException("Survey not found.");var r=t.Rows[0];litNo.Text=H(string.IsNullOrWhiteSpace(Convert.ToString(r["FixedAssetNo"]))?r["SurveyNo"]:r["FixedAssetNo"]);litName.Text=H(r["AssetName"]);litLocation.Text=H(r["BuildingName"]+" / "+r["FloorName"]+" / "+r["RoomName"]);litCustodian.Text=H(r["Custodian"]);hidQr.Value=string.IsNullOrWhiteSpace(Convert.ToString(r["FixedAssetNo"]))?Convert.ToString(r["SurveyNo"]):Convert.ToString(r["FixedAssetNo"]);}private string H(object v)=>Server.HtmlEncode(Convert.ToString(v));}}
